import React from 'react';

import { Link } from 'react-router-dom';

import { HikingBadgeOneLine } from '@apps/Hiking/@components/HikingBadge';
import { getRecipeUsagesByIdAsync } from '@apps/Recipes/@services/recipes.service';
import { IRecipeUsage } from '@apps/Recipes/@types/recipes.types';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

interface IRecipeUsagesProps {
  id_recipe: number;
}

const RecipeUsages: React.FC<IRecipeUsagesProps> = ({ id_recipe }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IRecipeUsage>();
  React.useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const d = await getRecipeUsagesByIdAsync(id_recipe);
        setData(d);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id_recipe]);

  if (isLoading) {
    return <PohLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }
  if (!data) {
    return <PohAlert variant={AlertVariant.Danger}>Has no usages data</PohAlert>;
  }

  return (
    <section>
      <h5>Количество использований</h5>
      <PohRow>
        <PohCol sm={6}>
          {data.byHiking.length > 0 ? (
            <>
              <h5>
                По походам <PohBadge>{data.byHiking.length}</PohBadge>
              </h5>
              <PohList
                data={data.byHiking.map((x) => {
                  return {
                    key: x.hiking.id,
                    children: (
                      <Link
                        to={`/hiking/${x.hiking.id}`}
                        className="d-flex align-items-center justify-content-between"
                      >
                        <HikingBadgeOneLine hiking={x.hiking} />
                        <PohBadge variant={BadgeVariant.Success}>{x.count}</PohBadge>
                      </Link>
                    ),
                  };
                })}
              />
            </>
          ) : (
            <Empty>Не использовался в походах</Empty>
          )}
        </PohCol>
        <PohCol sm={3}>
          {data.byHiking.length > 0 ? (
            <>
              <h5>
                По приёмам <PohBadge>{data.byAct.length}</PohBadge>
              </h5>
              <PohList
                data={data.byAct.map((x) => {
                  return {
                    key: x.act.id,
                    children: (
                      <div className="d-flex align-items-center justify-content-between">
                        {x.act.name}
                        <PohBadge variant={BadgeVariant.Success}>{x.count}</PohBadge>
                      </div>
                    ),
                  };
                })}
              />
            </>
          ) : (
            <Empty>Не использовался</Empty>
          )}
        </PohCol>
        <PohCol sm={3}>
          {data.byYear.length > 0 ? (
            <>
              <h5>
                По годам <PohBadge>{data.byYear.length}</PohBadge>
              </h5>
              <PohList
                data={data.byYear.map((x) => {
                  return {
                    key: x.year,
                    children: (
                      <div className="d-flex align-items-center justify-content-between">
                        {x.year}
                        <PohBadge variant={BadgeVariant.Success}>{x.count}</PohBadge>
                      </div>
                    ),
                  };
                })}
              />
            </>
          ) : (
            <Empty>Не использовался</Empty>
          )}
        </PohCol>
      </PohRow>
    </section>
  );
};

export default RecipeUsages;

export const RecipeUsagesWidget = (props: IRecipeUsagesProps) => {
  const [isOpen, setIsOpen] = React.useState(false);

  if (!isOpen)
    return (
      <PohButton block variant={ButtonVariant.Light} onClick={() => setIsOpen((c) => !c)}>
        Показать статистику использования
      </PohButton>
    );

  return <RecipeUsages {...props} />;
};
